let allTitles = [];
let allDescriptions = [];
let allKeywords = [];

for (const item of $json.items) {
  allTitles.push(item.title);
  allDescriptions.push(item.snippet);
  const keywords = item.title.toLowerCase().replace(/[^a-zA-Z0-9 ]/g, '').split(' ').filter(w => w.length > 3);
  allKeywords.push(...keywords);
}
const uniqueKeywords = [...new Set(allKeywords)];
return [{json:{chatInput:`Title List:\n${allTitles.join('\n')}\n\nDescription List:\n${allDescriptions.join('\n')}\n\nKeywords:\n${uniqueKeywords.join(', ')}`.trim()}}];

